head.script:
//
{
  "@context": "https://schema.org",
  "@graph": [
    {
      "@type": "WebSite",
      "@id": "https://digitalstudentadministration.blogspot.com/#website",
      "url": "https://digitalstudentadministration.blogspot.com/",
      "name": "Student Service Center (SSC)",
      "description": "Platform administrasi kesiswaan digital resmi untuk pengajuan surat keterangan aktif, pengantar PKL/magang, rekomendasi beasiswa, dan legalisir dokumen sekolah.",
      "inLanguage": "id-ID",
      "potentialAction": {
        "@type": "SearchAction",
        "target": "https://digitalstudentadministration.blogspot.com/p/layanan.html?q={search_term_string}",
        "query-input": "required name=search_term_string"
      }
    },
    {
      "@type": "EducationalOrganization",
      "@id": "https://digitalstudentadministration.blogspot.com/#organization",
      "name": "Student Service Center",
      "alternateName": "Pusat Layanan Kesiswaan Digital",
      "url": "https://digitalstudentadministration.blogspot.com/",
      "contactPoint": {
        "@type": "ContactPoint",
        "telephone": "+62-812-3456-7890",
        "contactType": "Customer Service",
        "areaServed": "ID",
        "availableLanguage": ["Indonesian"]
      },
      "address": {
        "@type": "PostalAddress",
        "streetAddress": "Gedung Administrasi Terpadu Lt. 1, Jl. Pendidikan No. 45",
        "addressLocality": "Kota Malang",
        "addressRegion": "Jawa Timur",
        "postalCode": "65145",
        "addressCountry": "ID"
      }
    },
    {
      "@type": "FAQPage",
      "@id": "https://digitalstudentadministration.blogspot.com/#faq",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Berapa lama proses pembuatan surat keterangan aktif siswa?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Proses pembuatan Surat Keterangan Siswa Aktif memakan waktu maksimal 1 hari kerja (24 jam) setelah pengajuan diverifikasi oleh staf Tata Usaha. Dokumen berformat PDF resmi dapat langsung diunduh dari dashboard siswa."
          }
        },
        {
          "@type": "Question",
          "name": "Apakah pengajuan surat administrasi di SSC dipungut biaya?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Tidak ada biaya sama sekali (100% GRATIS). Seluruh layanan administrasi kesiswaan yang disediakan oleh Student Service Center merupakan hak seluruh peserta didik aktif."
          }
        },
        {
          "@type": "Question",
          "name": "Bagaimana cara mengajukan Surat Pengantar PKL / Magang?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Siswa dapat masuk ke menu Layanan, pilih Surat Pengantar PKL, lalu isi form data perusahaan (nama instansi, alamat, narahubung/PIC, dan periode magang). Setelah disetujui Kaprog dan Kepala Sekolah, surat pengantar resmi diterbitkan."
          }
        },
        {
          "@type": "Question",
          "name": "Format dokumen apa yang diterima saat mengunggah berkas syarat?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Sistem menerima berkas lampiran berformat PDF, JPG, JPEG, dan PNG dengan ukuran file maksimal 5 MB per dokumen. Pastikan pindaian atau foto dokumen terlihat jelas dan terbaca."
          }
        },
        {
          "@type": "Question",
          "name": "Bagaimana cara melacak progres pengajuan surat yang sudah dibuat?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Anda dapat melacak status secara real-time melalui halaman Cek Pengajuan (/p/cek-pengajuan.html) dengan memasukkan Nomor Resi Pengajuan (contoh: REQ-2026-001) tanpa perlu login terlebih dahulu."
          }
        },
        {
          "@type": "Question",
          "name": "Apakah dokumen digital bertanda tangan elektronik dan QR Code sah?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ya, dokumen digital yang diterbitkan dilengkapi dengan kode verifikasi otentik dan QR Code resmi yang dapat dipindai oleh pihak eksternal (perusahaan, perbankan, dinas pendidikan) untuk memvalidasi keaslian surat."
          }
        }
      ]
    }
  ]
}
//

