(function(window, document) {
  "use strict";

  /* --- 1. CONFIGURATION --- */
  const SSC_CONFIG = {
    GAS_URL: "https://script.google.com/macros/s/AKfycbxEO8NcU9Aldj0WLDnJZSEZsog9A4NWsuRu3vEf2d5R3VmfZDFKT91jM11n1CwAT72z5Q/exec",
    IS_PREVIEW: false
  };

  /* --- PAGE URL MAPPING --- */
  const SSC_PAGES = {
    "home": "/",
    "beranda": "/",
