    "kontak": "/p/kontak.html",
    "login": "/p/login.html",
    "dashboard": "/p/dashboard.html",
    "admin": "/p/admin.html"
  };

  function navigateTo(pageId) {
    showLoadingBar(true);
    const targetUrl = SSC_PAGES[pageId] || ("/p/" + pageId + ".html");
    window.location.href = targetUrl;
  }
  window.navigateTo = navigateTo;

  /* --- 2. DUMMY DATABASE (OFFLINE & DEMO READY) --- */
