      { student_id: "STD-2026-001", nis: "2122101", nisn: "0051289110", name: "Arbi Pratama", class: "XII Rekayasa Perangkat Lunak 1", major: "RPL", email: "arbi.pratama@student.sch.id", phone: "081234567890", status: "Aktif" },
