      { student_id: "STD-2026-003", nis: "2122201", nisn: "0051289112", name: "Budi Santoso", class: "XI Teknik Komputer & Jaringan 2", major: "TKJ", email: "budi.santoso@student.sch.id", phone: "085678123456", status: "Aktif" }
    ],
