      { service_id: "SRV-REKOM", service_name: "Surat Rekomendasi Beasiswa", category: "Rekomendasi", description: "Rekomendasi resmi sekolah untuk pengajuan beasiswa prestasi.", requirements: "Bukti Prestasi / Formulir Beasiswa", estimated_days: 2, status: "active" },
      { service_id: "SRV-LEGALISIR", service_name: "Permohonan Legalisir Dokumen", category: "Akademik", description: "Pengesahan salinan rapor atau sertifikat kompetensi siswa.", requirements: "Scan Dokumen Asli yang akan dilegalisir", estimated_days: 2, status: "active" },
      { service_id: "SRV-IZIN", service_name: "Surat Dispensasi / Izin Khusus", category: "Administrasi", description: "Dispensasi meninggalkan KBM untuk tugas atau kejuaraan resmi.", requirements: "Surat Undangan Lomba / Penugasan", estimated_days: 1, status: "active" }
    ],
    submissions: [
      { submission_id: "REQ-2026-001", request_id: "REQ-2026-001", student_id: "STD-2026-001", student_name: "Arbi Pratama", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-AKTIF", service_name: "Surat Keterangan Siswa Aktif", submission_date: "2026-09-20 08:30", status: "SELESAI", notes: "Untuk tunjangan BPJS Ketenagakerjaan orang tua", document_url: "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf", admin_note: "Dokumen telah diverifikasi dan ditandatangani digital.", updated_at: "2026-09-20 14:00" },
      { submission_id: "REQ-2026-002", request_id: "REQ-2026-002", student_id: "STD-2026-001", student_name: "Arbi Pratama", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-MAGANG", service_name: "Surat Pengantar PKL / Magang", submission_date: "2026-09-21 10:15", status: "DIPROSES", notes: "Penempatan di PT Telkom Indonesia Malang", document_url: "", admin_note: "Menunggu paraf Kepala Program Keahlian", updated_at: "2026-09-21 11:30" },
      { submission_id: "REQ-2026-003", request_id: "REQ-2026-003", student_id: "STD-2026-002", student_name: "Siti Rahmawati", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-REKOM", service_name: "Surat Rekomendasi Beasiswa", submission_date: "2026-09-22 14:00", status: "MENUNGGU", notes: "Beasiswa Prestasi Pemprov Jawa Timur", document_url: "", admin_note: "", updated_at: "2026-09-22 14:00" },
      { submission_id: "REQ-2026-004", request_id: "REQ-2026-004", student_id: "STD-2026-003", student_name: "Budi Santoso", student_class: "XI Teknik Komputer & Jaringan 2", service_id: "SRV-LEGALISIR", service_name: "Permohonan Legalisir Dokumen", submission_date: "2026-09-23 09:15", status: "DIVERIFIKASI", notes: "Legalisir rapor semester 1-4", document_url: "", admin_note: "Berkas fotokopi telah diterima staf TU.", updated_at: "2026-09-23 10:15" }
    ],
    requests: [
      { submission_id: "REQ-2026-001", request_id: "REQ-2026-001", student_id: "STD-2026-001", student_name: "Arbi Pratama", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-AKTIF", service_name: "Surat Keterangan Siswa Aktif", submission_date: "2026-09-20 08:30", status: "SELESAI", notes: "Untuk tunjangan BPJS Ketenagakerjaan orang tua", document_url: "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf", admin_note: "Dokumen telah diverifikasi dan ditandatangani digital.", updated_at: "2026-09-20 14:00" },
      { submission_id: "REQ-2026-002", request_id: "REQ-2026-002", student_id: "STD-2026-001", student_name: "Arbi Pratama", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-MAGANG", service_name: "Surat Pengantar PKL / Magang", submission_date: "2026-09-21 10:15", status: "DIPROSES", notes: "Penempatan di PT Telkom Indonesia Malang", document_url: "", admin_note: "Menunggu paraf Kepala Program Keahlian", updated_at: "2026-09-21 11:30" },
      { submission_id: "REQ-2026-003", request_id: "REQ-2026-003", student_id: "STD-2026-002", student_name: "Siti Rahmawati", student_class: "XII Rekayasa Perangkat Lunak 1", service_id: "SRV-REKOM", service_name: "Surat Rekomendasi Beasiswa", submission_date: "2026-09-22 14:00", status: "MENUNGGU", notes: "Beasiswa Prestasi Pemprov Jawa Timur", document_url: "", admin_note: "", updated_at: "2026-09-22 14:00" }
    ],
    notifications: [
      { id: "NOTIF-01", recipient_id: "STD-2026-001", type: "success", title: "Surat Keterangan Aktif Telah Terbit", message: "Dokumen PDF resmi sudah dapat diunduh dari dashboard siswa.", is_read: false, created_at: "2026-09-20 14:00" },
      { id: "NOTIF-02", recipient_id: "STD-2026-001", type: "info", title: "Pengajuan Magang Sedang Diverifikasi", message: "Staf Tata Usaha sedang memeriksa kelengkapan data mitra DU/DI.", is_read: false, created_at: "2026-09-21 11:30" }
    ],
    documents: [
      { document_id: "DOC-01", submission_id: "REQ-2026-001", document_name: "Surat Keterangan Aktif - Arbi Pratama", service_name: "Surat Keterangan Siswa Aktif", pdf_url: "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf", created_at: "2026-09-20 14:00" }
    ],
    activity_logs: [
      { timestamp: "2026-09-23 10:15", user: "Admin TU", role: "Admin", action: "Verifikasi Berkas", description: "Memverifikasi berkas fisik permohonan legalisir REQ-2026-004" },
      { timestamp: "2026-09-22 14:00", user: "Siti Rahmawati", role: "Siswa", action: "Pengajuan Baru", description: "Mengajukan Surat Rekomendasi Beasiswa REQ-2026-003" },
      { timestamp: "2026-09-20 14:00", user: "Admin TU", role: "Admin", action: "Terbitkan Dokumen", description: "Menerbitkan PDF bertanda tangan digital REQ-2026-001" }
    ],
    reviews: [
      { review_id: "REV-01", author: "Farhan Maulana", role: "Siswa Kelas XII RPL 2", rating: 5, comment: "Pengajuan surat aktif siswa super kilat! Kurang dari 1 hari PDF sudah bisa langsung diunduh dari dashboard. Sangat memudahkan saat butuh cepat untuk perbankan.", date: "18 Sep 2026" },
      { review_id: "REV-02", author: "Aisyah Putri N.", role: "Siswa Kelas XI AKL 1", rating: 5, comment: "Tampilan websitenya sangat rapi dan mudah digunakan lewat HP. Fitur tracking pengajuannya sangat transparan jadi tidak perlu bolak-balik tanya ke ruang Tata Usaha.", date: "15 Sep 2026" },
      { review_id: "REV-03", author: "Drs. Hendro Wibowo", role: "Guru BK / Staf TU", rating: 5, comment: "Beban kerja administrasi manual berkurang drastis sejak ada sistem SSC ini. Semua arsip tersusun rapi di Google Drive dan terhubung langsung ke Google Sheets.", date: "10 Sep 2026" }
    ]
  };

  function loadDatabase() {
    let db = null;
    try {
      const stored = localStorage.getItem("ssc_dummy_database");
      if (stored) db = JSON.parse(stored);
    } catch(e) {}

    // Auto-heal missing collections if loaded from older cache
    if (!db || !Array.isArray(db.submissions) || !Array.isArray(db.notifications) || !Array.isArray(db.documents) || !Array.isArray(db.activity_logs)) {
      db = Object.assign({}, INITIAL_DB);
      try { localStorage.setItem("ssc_dummy_database", JSON.stringify(db)); } catch(e) {}
    }
    return db;
  }

  const DUMMY_DB = loadDatabase();

  function saveDatabase() {
    try {
      localStorage.setItem("ssc_dummy_database", JSON.stringify(DUMMY_DB));
      window.dispatchEvent(new CustomEvent("ssc_db_updated", { detail: DUMMY_DB }));
    } catch(e) {}
  }

  // Cross-tab real-time sync listener
  window.addEventListener("storage", function(e) {
    if (e.key === "ssc_dummy_database" && e.newValue) {
      try {
        var fresh = JSON.parse(e.newValue);
        if (fresh) {
          if (Array.isArray(fresh.submissions)) {
            DUMMY_DB.submissions = fresh.submissions;
            DUMMY_DB.requests = fresh.submissions;
          }
          if (Array.isArray(fresh.notifications)) DUMMY_DB.notifications = fresh.notifications;
          if (Array.isArray(fresh.documents)) DUMMY_DB.documents = fresh.documents;
          if (Array.isArray(fresh.activity_logs)) DUMMY_DB.activity_logs = fresh.activity_logs;
          window.dispatchEvent(new CustomEvent("ssc_db_updated", { detail: DUMMY_DB }));
        }
      } catch(err) {}
    }
  });

  /* --- 3. SESSION STATE --- */
  let CURRENT_SESSION = (function() {
    try {
      const sess = sessionStorage.getItem("ssc_active_session");
      if (sess) return JSON.parse(sess);
    } catch(e) {}
    return null;
  })();

  /* --- 4. BACKEND INTEGRATION (GAS / FALLBACK) --- */
  function callGAS(action, payload) {
    if (!SSC_CONFIG.GAS_URL || SSC_CONFIG.GAS_URL.trim() === "" || SSC_CONFIG.IS_PREVIEW) {
      return mockGASCall(action, payload);
    }
    return fetch(SSC_CONFIG.GAS_URL, {
      method: "POST",
      mode: "cors",
      headers: { "Content-Type": "text/plain;charset=utf-8" },
      body: JSON.stringify(Object.assign({ action: action }, payload || {}))
    })
    .then(function(res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    })
    .then(function(json) {
      if (action === "syncAll" && json && json.status === "success" && json.data) {
        if (Array.isArray(json.data.submissions)) {
          DUMMY_DB.submissions = json.data.submissions;
          DUMMY_DB.requests = json.data.submissions;
        }
        if (Array.isArray(json.data.services) && json.data.services.length > 0) DUMMY_DB.services = json.data.services;
        if (Array.isArray(json.data.students) && json.data.students.length > 0) DUMMY_DB.students = json.data.students;
        if (Array.isArray(json.data.documents)) DUMMY_DB.documents = json.data.documents;
        if (Array.isArray(json.data.notifications)) DUMMY_DB.notifications = json.data.notifications;
        if (Array.isArray(json.data.activity_logs)) DUMMY_DB.activity_logs = json.data.activity_logs;
        saveDatabase();
      } else if (action === "createSubmission" && json && json.status === "success") {
        var rec = json.data || (payload && payload.data);
        if (rec) {
          if (!Array.isArray(DUMMY_DB.submissions)) DUMMY_DB.submissions = [];
          var exists = DUMMY_DB.submissions.some(function(s){ return s.submission_id === rec.submission_id; });
          if (!exists) {
            DUMMY_DB.submissions.unshift(rec);
            if (Array.isArray(DUMMY_DB.requests)) DUMMY_DB.requests.unshift(rec);
          }
          saveDatabase();
        }
      } else if (action === "updateSubmissionStatus" && json && json.status === "success") {
        var id = payload.submission_id;
        var sub = (DUMMY_DB.submissions || []).find(function(s){ return s.submission_id === id || s.request_id === id; });
        if (sub) {
          sub.status = payload.status;
          if (payload.note) sub.admin_note = payload.note;
          sub.updated_at = new Date().toISOString().replace("T", " ").substring(0, 16);
          saveDatabase();
        }
      }
      return json;
    })
    .catch(function(err) {
      console.warn("GAS Connection failed, using mock data:", err);
      return mockGASCall(action, payload);
    });
  }

  function mockGASCall(action, payload) {
    return new Promise(function(resolve) {
      setTimeout(function() {
        if (action === "login") {
          const user = DUMMY_DB.users.find(function(u) {
            return u.username.toLowerCase() === (payload.username || "").toLowerCase() &&
                   u.password === payload.password &&
                   u.role === payload.role;
          });
          if (user) {
            let studentData = null;
            if (user.role === "student") {
              studentData = DUMMY_DB.students.find(function(s) { return s.student_id === user.student_id; }) || null;
            }
            resolve({
              status: "success",
              message: "Login berhasil!",
              user: {
                user_id: user.user_id,
                username: user.username,
                role: user.role,
                name: user.name,
                student: studentData
              }
            });
          } else {
            resolve({ status: "error", message: "Username, password, atau peran tidak sesuai." });
          }
        } else if (action === "trackRequest" || action === "trackSubmission") {
          const code = (payload.trackingCode || payload.ticket || payload.submission_id || "").trim().toUpperCase();
          const req = (DUMMY_DB.submissions || DUMMY_DB.requests || []).find(function(r) {
            return (r.submission_id || "").toUpperCase() === code || (r.request_id || "").toUpperCase() === code;
          });
          if (req) {
            resolve({ status: "success", data: req });
          } else {
            resolve({ status: "error", message: "Nomor resi pengajuan tidak ditemukan dalam database." });
          }
        } else if (action === "createSubmission" || action === "createRequest") {
          var data = payload.data || payload;
          var newId = data.submission_id || ("SSC-" + new Date().getFullYear() + "-" + Math.floor(10000 + Math.random() * 89999));
          var now = new Date().toISOString().replace("T", " ").substring(0, 16);
          var record = {
            submission_id: newId,
            request_id: newId,
            student_id: data.student_id || "STD-2026-001",
            student_name: data.student_name || "Arbi Pratama",
            student_class: data.student_class || data.class || "XII RPL 1",
            service_id: data.service_id || "SRV-AKTIF",
            service_name: data.service_name || "Surat Keterangan Siswa Aktif",
            submission_date: data.submission_date || now,
            purpose: data.purpose || data.notes || "-",
            attachment_url: data.attachment_url || "",
            attachment_name: data.attachment_name || "",
            status: data.status || "MENUNGGU",
            admin_note: data.admin_note || "Menunggu verifikasi staf TU.",
            document_url: data.document_url || "",
            updated_at: data.updated_at || now
          };
          if (!Array.isArray(DUMMY_DB.submissions)) DUMMY_DB.submissions = [];
          if (!Array.isArray(DUMMY_DB.requests)) DUMMY_DB.requests = [];
          DUMMY_DB.submissions.unshift(record);
          DUMMY_DB.requests.unshift(record);
          if (!Array.isArray(DUMMY_DB.activity_logs)) DUMMY_DB.activity_logs = [];
          DUMMY_DB.activity_logs.unshift({
            timestamp: now,
            user: record.student_name,
            role: "Siswa",
            action: "Pengajuan Baru",
            description: "Mengajukan " + record.service_name + " (" + newId + ")"
          });
          saveDatabase();
          resolve({ status: "success", message: "Pengajuan berhasil dikirimkan!", submission_id: newId, data: record });
        } else if (action === "uploadAttachment") {
          var fileUrl = payload.base64Data ? 
            (payload.base64Data.indexOf("data:") === 0 ? payload.base64Data : ("data:" + (payload.mimeType || "application/octet-stream") + ";base64," + payload.base64Data)) :
            "https://drive.google.com/uc?export=download&id=mock-" + Date.now();
          resolve({ status: "success", file_id: "FILE-" + Date.now(), file_url: fileUrl, download_url: fileUrl });
        } else if (action === "updateSubmissionStatus") {
          var id = payload.submission_id;
          var sub = (DUMMY_DB.submissions || []).find(function(s){ return s.submission_id === id || s.request_id === id; });
          if (sub) {
            sub.status = payload.status;
            if (payload.note) sub.admin_note = payload.note;
            if (payload.status === "SELESAI" && !sub.document_url) {
              sub.document_url = "https://www.w3.org/WAI/ER/tests/xhtml/testfiles/resources/pdf/dummy.pdf";
            }
            sub.updated_at = new Date().toISOString().replace("T", " ").substring(0, 16);
            if (Array.isArray(DUMMY_DB.requests)) {
              var req = DUMMY_DB.requests.find(function(r){ return r.submission_id === id || r.request_id === id; });
              if (req) {
                req.status = sub.status;
                req.admin_note = sub.admin_note;
                req.document_url = sub.document_url;
                req.updated_at = sub.updated_at;
              }
            }
            saveDatabase();
            resolve({ status: "success", message: "Status pengajuan berhasil diperbarui.", data: sub });
          } else {
            resolve({ status: "error", message: "Pengajuan " + id + " tidak ditemukan." });
          }
        } else if (action === "getAllSubmissions") {
          resolve({ status: "success", data: DUMMY_DB.submissions || [] });
        } else if (action === "getStudentSubmissions") {
          var list = (DUMMY_DB.submissions || []).filter(function(s){ return s.student_id === payload.student_id; });
          resolve({ status: "success", data: list });
        } else if (action === "getServices" || action === "getServicesList" || action === "getPublicServices") {
          resolve({ status: "success", data: DUMMY_DB.services });
        } else if (action === "syncAll") {
          resolve({
            status: "success",
            data: {
              services: DUMMY_DB.services || [],
              students: DUMMY_DB.students || [],
              submissions: DUMMY_DB.submissions || [],
              documents: DUMMY_DB.documents || [],
              notifications: DUMMY_DB.notifications || [],
              activity_logs: DUMMY_DB.activity_logs || []
            }
          });
        } else {
          resolve({ status: "success", data: DUMMY_DB });
        }
      }, 350);
    });
  }

  /* --- 5. UI UTILITIES --- */
  function showLoadingBar(show) {
    const bar = document.getElementById("pageLoadingBar");
    if (!bar) return;
    if (show === false) {
      bar.style.opacity = "0";
      setTimeout(function() { bar.style.display = "none"; }, 300);
    } else {
      bar.style.display = "block";
      bar.style.opacity = "1";
    }
  }

  function showToast(message, type) {
    const toastEl = document.getElementById("liveToast");
    const msgEl = document.getElementById("toastMessage");
    if (!toastEl || !msgEl) {
      alert(message);
      return;
    }
    toastEl.className = "toast align-items-center text-white border-0 rounded-3 shadow-lg";
    if (type === "success") toastEl.classList.add("bg-success");
    else if (type === "error" || type === "danger") toastEl.classList.add("bg-danger");
    else if (type === "warning") toastEl.classList.add("bg-warning", "text-dark");
    else toastEl.classList.add("bg-primary");

    const icon = type === "success" ? "fa-circle-check" : type === "error" ? "fa-circle-exclamation" : "fa-circle-info";
    msgEl.innerHTML = '<i class="fa-solid ' + icon + ' fs-5"></i> <span>' + message + '</span>';

    try {
      const toast = new bootstrap.Toast(toastEl, { delay: 3500 });
      toast.show();
    } catch(e) {
      toastEl.classList.add("show");
      setTimeout(function() { toastEl.classList.remove("show"); }, 3500);
    }
  }

  function toggleSidebar() {
    const sidebar = document.getElementById("appSidebar");
    const overlay = document.getElementById("sidebarMobileOverlay");
    if (!sidebar) return;
    const isOpen = sidebar.classList.contains("open") || sidebar.classList.contains("show");
    if (isOpen) {
      sidebar.classList.remove("open", "show");
      if (overlay) overlay.classList.remove("open", "show");
      document.body.style.overflow = "";
    } else {
      sidebar.classList.add("open", "show");
      if (overlay) overlay.classList.add("open", "show");
      if (window.innerWidth < 992) document.body.style.overflow = "hidden";
    }
  }

  function closeSidebar() {
    const sidebar = document.getElementById("appSidebar");
    const overlay = document.getElementById("sidebarMobileOverlay");
    if (sidebar) sidebar.classList.remove("open", "show");
    if (overlay) overlay.classList.remove("open", "show");
    document.body.style.overflow = "";
  }

  /* Modal Controllers */
  function openLoginModal(role) {
    const modal = document.getElementById("loginModal");
    if (!modal) {
      window.location.href = role === "admin" ? "/p/login.html?role=admin" : "/p/login.html";
      return;
    }
    modal.classList.add("show");
    document.body.style.overflow = "hidden";
    if (role === "admin") {
      const rad = document.getElementById("roleAdmin");
      if (rad) rad.checked = true;
    } else {
      const rad = document.getElementById("roleStudent");
      if (rad) rad.checked = true;
    }
  }

  function closeLoginModal() {
    const modal = document.getElementById("loginModal");
    if (!modal) return;
    modal.classList.remove("show");
    document.body.style.overflow = "";
  }

  function openReviewModal() {
    const modal = document.getElementById("reviewModal");
    if (!modal) return;
    modal.classList.add("show");
    document.body.style.overflow = "hidden";
  }

  function closeReviewModal() {
    const modal = document.getElementById("reviewModal");
    if (!modal) return;
    modal.classList.remove("show");
    document.body.style.overflow = "";
  }

  function autoFillAndSubmit(role) {
    const uInput = document.getElementById("loginUsername");
    const pInput = document.getElementById("loginPassword");
    if (role === "admin") {
      if (uInput) uInput.value = "admin";
      if (pInput) pInput.value = "admin2026";
      const rad = document.getElementById("roleAdmin");
      if (rad) rad.checked = true;
    } else {
      if (uInput) uInput.value = "peserta";
      if (pInput) pInput.value = "edudigital";
      const rad = document.getElementById("roleStudent");
      if (rad) rad.checked = true;
    }
    handleLoginSubmit();
  }

  function togglePasswordVisibility(fieldId, iconBtn) {
    const field = document.getElementById(fieldId);
    if (!field) return;
    if (field.type === "password") {
      field.type = "text";
      if (iconBtn) iconBtn.innerHTML = '<i class="fa-solid fa-eye-slash"></i>';
    } else {
      field.type = "password";
      if (iconBtn) iconBtn.innerHTML = '<i class="fa-solid fa-eye"></i>';
    }
  }

  function handleLoginSubmit() {
    const uInput = document.getElementById("loginUsername");
    const pInput = document.getElementById("loginPassword");
    const errBox = document.getElementById("loginErrorAlert");
    const errText = document.getElementById("loginErrorMessage");
    const btn = document.getElementById("btnLoginSubmit");

    if (errBox) errBox.classList.add("d-none");

    const username = uInput ? uInput.value.trim() : "";
    const password = pInput ? pInput.value.trim() : "";
    const roleAdminRad = document.getElementById("roleAdmin");
    const role = (roleAdminRad && roleAdminRad.checked) ? "admin" : "student";

    if (!username || !password) {
      if (errBox && errText) {
        errText.textContent = "Silakan isi username dan password.";
        errBox.classList.remove("d-none");
      } else {
        showToast("Silakan isi username dan password.", "warning");
      }
      return;
    }

    if (btn) {
      btn.disabled = true;
      btn.innerHTML = '<span class="spinner-border spinner-border-sm me-2"></span> Memproses...';
    }

    callGAS("login", { username: username, password: password, role: role })
      .then(function(res) {
        if (res.status === "success") {
          CURRENT_SESSION = res.user;
          sessionStorage.setItem("ssc_active_session", JSON.stringify(res.user));
          showToast("Login berhasil! Mengalihkan...", "success");
          closeLoginModal();
          setTimeout(function() {
            window.location.href = role === "admin" ? "/p/admin.html" : "/p/dashboard.html";
          }, 500);
        } else {
          if (errBox && errText) {
            errText.textContent = res.message || "Login gagal.";
            errBox.classList.remove("d-none");
          } else {
            showToast(res.message || "Login gagal.", "danger");
          }
        }
      })
      .finally(function() {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<i class="fa-solid fa-right-to-bracket me-2"></i> Masuk Sekarang';
        }
      });
  }

  function handleLogout() {
    CURRENT_SESSION = null;
    sessionStorage.removeItem("ssc_active_session");
    localStorage.removeItem("ssc_active_session");
    showToast("Anda telah keluar.", "info");
    setTimeout(function() {
      window.location.href = "/";
    }, 300);
  }

  /* FAQ Filtering Functions */
  function filterFaq() {
    const q = (document.getElementById("faq-search-input")?.value || "").toLowerCase().trim();
    const items = document.querySelectorAll("#faqAccordion .accordion-item");
    items.forEach(function(item) {
      const text = item.innerText.toLowerCase();
      item.style.display = (!q || text.includes(q)) ? "" : "none";
    });
  }
  window.filterFaq = filterFaq;

  function filterFaqByCategory(cat, btn) {
    document.querySelectorAll(".faq-cat-btn").forEach(function(b) { b.classList.remove("active"); });
    if (btn) btn.classList.add("active");
    const items = document.querySelectorAll("#faqAccordion .accordion-item");
    items.forEach(function(item) {
      const c = item.getAttribute("data-category") || "";
      item.style.display = (cat === "all" || c === cat) ? "" : "none";
    });
  }
  window.filterFaqByCategory = filterFaqByCategory;

  /* --- 6. PAGE INITIALIZATION & ROUTING --- */

  /* --- 1.1 SELF-HEALING CLIENT ROUTER (100% RELIABILITY GUARANTEE) --- */
  const SSC_PAGE_TEMPLATES = {
    "layanan": "",
    "cara-kerja": "",
    "cek-pengajuan": "",
    "blog": "",
    "kontak": "",
    "login": "",
    "dashboard": "",
    "admin": "",
  };

  function decodeTemplate(b64) {
    try {
      return decodeURIComponent(escape(window.atob(b64)));
    } catch (e) {
      console.error('[SSC Router] Decode error:', e);
      return '';
    }
  }

  function mountSelfHealingPage() {
    const path = (window.location.pathname || '').toLowerCase();
    // Homepage is served natively by #ssc-beranda-page
    if (path === '/' || path === '' || path.endsWith('/p/beranda.html') || path.endsWith('/p/beranda')) {
      const berandaEl = document.getElementById('ssc-beranda-page');
      if (berandaEl) berandaEl.style.display = 'block';
      return;
    }

    // Check which page matches
    const pageKeys = ['layanan', 'cara-kerja', 'cek-pengajuan', 'blog', 'kontak', 'login', 'dashboard', 'admin'];
    let targetKey = null;
    for (let i = 0; i < pageKeys.length; i++) {
      if (path.includes(pageKeys[i])) {
        targetKey = pageKeys[i];
        break;
      }
    }

    if (!targetKey) return;

    const berandaEl = document.getElementById('ssc-beranda-page');
    if (berandaEl) berandaEl.style.display = 'none';

    // Check if Blogger natively rendered content into post-body
    const nativePost = document.querySelector('.ssc-post-content, .post-body, .entry-content');
    const hasNativeText = nativePost && nativePost.innerText.trim().length > 40;

          if (!hasNativeText) {
      const mount = document.getElementById('ssc-client-mount') || document.getElementById('main');
      if (mount && !mount.hasAttribute('data-ssc-mounted')) {
        mount.setAttribute('data-ssc-mounted', targetKey);
        console.info('[SSC Self-Healing] Native Blogger post body empty. Rendering fallback view for:', targetKey);
        const rawHtml = decodeTemplate(SSC_PAGE_TEMPLATES[targetKey] || '');
        if (rawHtml) {
          mount.innerHTML = rawHtml;
          // Execute any embedded scripts safely
          const scripts = mount.querySelectorAll('script');
          scripts.forEach(function(s) {
            if (s.type === 'application/ld+json') return;
            const n = document.createElement('script');
            Array.from(s.attributes).forEach(function(attr) { n.setAttribute(attr.name, attr.value); });
            n.textContent = s.textContent;
            s.parentNode.replaceChild(n, s);
          });

          // Update UI modes if login, dashboard or admin
          if (targetKey === 'login' || targetKey === 'dashboard' || targetKey === 'admin') {
            const nav = document.getElementById('public-navbar');
            const footer = document.getElementById('ssc-footer');
            const floating = document.getElementById('floatingStack');
            if (nav) nav.style.display = 'none';
            if (footer) footer.style.display = 'none';
            if (floating) {
            floating.style.setProperty('display', 'none', 'important');
            floating.style.setProperty('visibility', 'hidden', 'important');
          }
          document.body.classList.add('page-clean-view');
          }

          // Immediately invoke pageInit hook for SPA / mounted view
          setTimeout(function() {
            if (typeof window.SSC_pageInit === 'function') {
              try {
                window.SSC_pageInit(CURRENT_SESSION, DUMMY_DB, SSC_CONFIG);
              } catch(e) {
                console.warn('[SSC Router] Error in pageInit:', e);
              }
            }
          }, 30);

          // Trigger scroll reveal animations
          if (typeof setupReveal === 'function') setupReveal();
        }
      }
    }
  }

  function initPortal() {
    setupReveal();
    setupBackToTop();
    mountSelfHealingPage();
    setupNavbarScroll();

    const path = (window.location.pathname || "").toLowerCase();
    const pageVar = (window.SSC_PAGE || "").toLowerCase();

    // Auto-redirect URL alias for articles to prevent 404
    if (path.includes("cara-cepat-mendapatkan-surat-keterangan") && !path.includes("_01885387324")) {
      window.location.replace("/p/cara-cepat-mendapatkan-surat-keterangan_01885387324.html");
      return;
    }

    // Strictly check for full-screen internal app views (never match general admin / preview paths)
    const isDashboard = pageVar === "dashboard" || path.endsWith("/p/dashboard.html") || path.endsWith("/p/dashboard");
    const isAdmin = pageVar === "admin" || path.endsWith("/p/admin.html") || path.endsWith("/p/admin");
    const isLogin = pageVar === "login" || path.endsWith("/p/login.html") || path.endsWith("/p/login");

    const nav = document.getElementById("public-navbar");
    const footer = document.getElementById("ssc-footer");
    const floating = document.getElementById("floatingStack");

    if (isDashboard || isAdmin || isLogin) {
      if (nav) nav.style.display = "none";
      if (footer) footer.style.display = "none";
      if (floating) {
        floating.style.setProperty("display", "none", "important");
        floating.style.setProperty("visibility", "hidden", "important");
      }
      document.body.classList.add("page-clean-view");

      // Auto authenticate demo if session is empty
      if (isDashboard && (!CURRENT_SESSION || CURRENT_SESSION.role !== "student")) {
        CURRENT_SESSION = DUMMY_DB.users[1]; // Arbi Pratama
        sessionStorage.setItem("ssc_active_session", JSON.stringify(CURRENT_SESSION));
      }
      if (isAdmin && (!CURRENT_SESSION || CURRENT_SESSION.role !== "admin")) {
        CURRENT_SESSION = DUMMY_DB.users[0]; // Admin TU
        sessionStorage.setItem("ssc_active_session", JSON.stringify(CURRENT_SESSION));
      }
    } else {
      if (nav) nav.style.display = "";
      if (footer) {
        footer.style.display = "block";
        footer.style.visibility = "visible";
        footer.style.opacity = "1";
      }
      if (floating) floating.style.display = "";
      updateNavbarAuth();
      highlightActiveNavLink(path);
    }

    // If page defined SSC_pageInit hook, call it
    if (typeof window.SSC_pageInit === "function") {
      try {
        window.SSC_pageInit(CURRENT_SESSION, DUMMY_DB, SSC_CONFIG);
      } catch(err) {
        console.warn("SSC_pageInit error:", err);
      }
    }

    showLoadingBar(false);
  }

  function highlightActiveNavLink(path) {
    document.querySelectorAll("#mainNavLinks .nav-link").forEach(function(l) { l.classList.remove("active"); });
    if (path.includes("layanan")) {
      const el = document.getElementById("navlink-layanan");
      if (el) el.classList.add("active");
    } else if (path.includes("cara-kerja")) {
      const el = document.getElementById("navlink-cara-kerja");
      if (el) el.classList.add("active");
    } else if (path.includes("cek-pengajuan") || path.includes("track")) {
      const el = document.getElementById("navlink-cek-pengajuan");
      if (el) el.classList.add("active");
    } else if (path.includes("blog")) {
      const el = document.getElementById("navlink-blog");
      if (el) el.classList.add("active");
    } else if (path.includes("kontak")) {
      const el = document.getElementById("navlink-kontak");
      if (el) el.classList.add("active");
    } else {
      const el = document.getElementById("navlink-home");
      if (el) el.classList.add("active");
    }
  }

  function updateNavbarAuth() {
    const unauth = document.getElementById("navUnauthBtns");
    const auth = document.getElementById("navAuthUser");
    const nameEl = document.getElementById("navUserName");
    const avatarEl = document.getElementById("navUserAvatar");
    const roleLabel = document.getElementById("navUserRoleLabel");
    const dashLink = document.getElementById("navDashboardLink");

    if (CURRENT_SESSION && CURRENT_SESSION.name) {
      if (unauth) unauth.classList.add("d-none");
      if (auth) {
        auth.classList.remove("d-none");
        auth.classList.add("d-flex");
      }
      if (nameEl) nameEl.textContent = CURRENT_SESSION.name;
      if (avatarEl) avatarEl.textContent = CURRENT_SESSION.name.charAt(0).toUpperCase();
      if (roleLabel) roleLabel.textContent = CURRENT_SESSION.role === "admin" ? "Admin Tata Usaha" : "Siswa Aktif";
      if (dashLink) {
        dashLink.href = CURRENT_SESSION.role === "admin" ? "/p/admin.html" : "/p/dashboard.html";
        dashLink.innerHTML = CURRENT_SESSION.role === "admin"
          ? '<i class="fa-solid fa-gauge me-2 text-danger"></i> Panel Admin'
          : '<i class="fa-solid fa-chart-line me-2 text-primary"></i> Dashboard Siswa';
      }
    } else {
      if (unauth) unauth.classList.remove("d-none");
      if (auth) {
        auth.classList.remove("d-flex");
        auth.classList.add("d-none");
      }
    }
  }

  /* --- 7. SCROLL ANIMATIONS --- */
  function setupReveal() {
    if (!("IntersectionObserver" in window)) {
      document.querySelectorAll(".reveal").forEach(function(el) { el.classList.add("revealed"); });
      return;
    }
    const observer = new IntersectionObserver(function(entries) {
      entries.forEach(function(entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add("revealed");
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.05, rootMargin: "0px 0px -20px 0px" });

    document.querySelectorAll(".reveal:not(.revealed)").forEach(function(el) {
      observer.observe(el);
    });
    window.__revealObserver = observer;
  }

  function setupBackToTop() {
    const btn = document.getElementById("backToTop");
    if (!btn) return;
    window.addEventListener("scroll", function() {
      if (window.scrollY > 280) {
        btn.classList.add("visible");
      } else {
        btn.classList.remove("visible");
      }
    }, { passive: true });

    btn.addEventListener("click", function() {
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }

  function setupNavbarScroll() {
    const nav = document.getElementById("public-navbar");
    if (nav) {
      window.addEventListener("scroll", function() {
        nav.classList.toggle("nav-scrolled", window.scrollY > 20);
      }, { passive: true });
      nav.classList.toggle("nav-scrolled", window.scrollY > 20);
    }

    // Auto close mobile navbar collapse when clicking link
    const navCollapse = document.getElementById("navPublicMenu");
    if (navCollapse) {
      navCollapse.querySelectorAll(".nav-link, .btn").forEach(function(link) {
        link.addEventListener("click", function() {
          if (window.innerWidth < 992 && navCollapse.classList.contains("show")) {
            try {
              const bsCollapse = bootstrap.Collapse.getInstance(navCollapse) || new bootstrap.Collapse(navCollapse);
              bsCollapse.hide();
            } catch(e) {
              navCollapse.classList.remove("show");
            }
          }
        });
      });
    }
  }

  /* --- 8. EXPOSE GLOBAL SSC API --- */

  function statusBadgeClass(status) {
    if (!status) return "badge-menunggu";
    const s = String(status).toUpperCase();
    if (s === "SELESAI") return "badge-selesai";
    if (s === "DISETUJUI") return "badge-disetujui";
    if (s === "DIPROSES") return "badge-diproses";
    if (s === "DIVERIFIKASI") return "badge-diverifikasi";
    if (s === "DITOLAK") return "badge-ditolak";
    if (s.includes("REVISI")) return "badge-perlu-revisi";
    return "badge-menunggu";
  }
  window.statusBadgeClass = statusBadgeClass;

  const SSC = {
    statusBadgeClass: statusBadgeClass,
    config: SSC_CONFIG,
    db: DUMMY_DB,
    saveDatabase: saveDatabase,
    getSession: function() { return CURRENT_SESSION; },
    setSession: function(s) { CURRENT_SESSION = s; sessionStorage.setItem("ssc_active_session", JSON.stringify(s)); updateNavbarAuth(); },
    callGAS: callGAS,
    showToast: showToast,
    showLoadingBar: showLoadingBar,
    toggleSidebar: toggleSidebar,
    closeSidebar: closeSidebar,
    openLoginModal: openLoginModal,
    closeLoginModal: closeLoginModal,
    openReviewModal: openReviewModal,
    closeReviewModal: closeReviewModal,
    autoFillAndSubmit: autoFillAndSubmit,
    togglePasswordVisibility: togglePasswordVisibility,
    handleLoginSubmit: handleLoginSubmit,
    handleLogout: handleLogout,
    setupReveal: setupReveal,
    init: initPortal
  };

  window.SSC = SSC;

  // Window aliases
  window.showToast = showToast;
  window.toggleSidebar = toggleSidebar;
  window.closeSidebar = closeSidebar;
  window.openLoginModal = openLoginModal;
  window.closeLoginModal = closeLoginModal;
  window.openReviewModal = openReviewModal;
  window.closeReviewModal = closeReviewModal;
  window.autoFillAndSubmit = autoFillAndSubmit;
  window.togglePasswordVisibility = togglePasswordVisibility;
  window.handleLoginSubmit = handleLoginSubmit;
  window.handleLogout = handleLogout;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initPortal);
  } else {
    initPortal();
  }

})(window, document);
